describe('Navigation between home page and example pages', () => {
  const baseUrl = 'https://the-internet.herokuapp.com';

  beforeEach(() => {
    cy.visit(baseUrl);
  });

  it('should display welcome heading on home page and navigate to A/B Testing example', () => {
    // Verify home page displays correct heading
    cy.get('h1').should('contain', 'Welcome to the-internet');

    // Click on A/B Testing link
    cy.contains('a', 'A/B Testing').click();

    // Verify URL contains /abtest
    cy.url().should('include', '/abtest');

    // Verify h3 heading is present on the example page
    cy.get('h3').should('be.visible');
  });

  it('should navigate back to home page and display Available Examples heading', () => {
    // Navigate to A/B Testing example
    cy.contains('a', 'A/B Testing').click();

    // Verify we are on the abtest page
    cy.url().should('include', '/abtest');

    // Navigate back to home page
    cy.go('back');

    // Verify we are back on the home page
    cy.url().should('eq', baseUrl + '/');

    // Verify the Available Examples heading is visible
    cy.contains('h2', 'Available Examples').should('be.visible');
  });

  it('should handle navigation when clicking multiple links sequentially', () => {
    // Verify initial home page state
    cy.get('h1').should('contain', 'Welcome to the-internet');

    // Navigate to A/B Testing
    cy.contains('a', 'A/B Testing').click();
    cy.url().should('include', '/abtest');

    // Go back to home
    cy.go('back');
    cy.contains('h2', 'Available Examples').should('be.visible');

    // Navigate to another example to verify the pattern works
    cy.contains('a', 'Broken Images').click();
    cy.url().should('include', '/broken_images');

    // Go back again
    cy.go('back');
    cy.get('h1').should('contain', 'Welcome to the-internet');
  });
});
